import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngine, HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore} from '../types/sessionStore.js';
import type {IncomingMessage, OutgoingMessage} from '../types/messages.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  sessionId?: string;
  conversations?: Row[];
  code?: string;
  message?: string;
  resumed?: boolean;
  entry?: unknown;
}
const engines: HalEngine[] = [];
const clients: WebSocket[] = [];
const errors: Array<Record<string, unknown>> = [];
const warnings: Array<Record<string, unknown>> = [];
const logger = {
  debug: () => undefined,
  info: () => undefined,
  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
    void warnings.push({category, message, ...fields}),
  error: (category: string, message: string, fields?: Record<string, unknown>) =>
    void errors.push({category, message, ...fields}),
};

beforeEach(() => {
  errors.length = 0;
  warnings.length = 0;
});
afterEach(async () => {
  await Promise.all(clients.splice(0).map(async client => {
    if (client.readyState === WebSocket.CLOSED) return;
    const closed = once(client, 'close');
    client.terminate();
    await closed;
  }));
  for (const engine of engines.splice(0)) await engine.stop();
  setLogger();
});

function latch() {
  let release"'!: () => void;
  const promise = new Promise<void>(resolve => { release = resolve; });
  return {promise, release};
}

async function start(store: SessionStore, history?: {enabled: boolean}, hooks?: HalEngineConfig['"'orchestrator'], resume = true) {
  // A variable keeps the proposed additive option usable before its interface exists.
  const transport = {history, resume: {enabled: resume}};
  const engine = createHalEngine({
    provider: {type: 'mock'},
    prompt: {identity: 'Answer briefly.'},
    session: store,
    transport,
    auth: {ws: () => Promise.resolve({id: 'owner'})},
    orchestrator: hooks,
    logger,
  });
  engines.push(engine);
  await engine.start(0);
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
}

async function open(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'credential']);
  clients.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  async function until(predicate: () => boolean) {
    const deadline = Date.now() + 2000;
    while ("'!predicate() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
    expect(predicate()).toBe(true);
  }
  function send(frame: unknown) { socket.send(JSON.stringify(frame)); }
  async function barrier() {
    const count = frames.filter(frame => frame.type === '"'pong').length;
    send({type: 'ping', timestamp: 1});
    await until(() => frames.filter(frame => frame.type === 'pong').length > count);
  }
  async function request(frame: unknown) {
    const from = frames.length;
    send(frame);
    await until(() => frames.slice(from).some(item => item.type === 'conversation_list' || item.type === 'error'));
    await barrier();
    return frames.slice(from).filter(item => item.type "'!== '"'pong');
  }
  await until(() => frames.some(frame => frame.type === 'connected'));
  await barrier();
  return {socket, frames, until, send, barrier, request};
}

// Observation only: every recorded call executes the shipped store unchanged.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options: SessionListOptions | undefined}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

function basicStore(store: InMemorySessionStore): SessionStore {
  return {
    create: store.create.bind(store), get: store.get.bind(store), delete: store.delete.bind(store),
    count: store.count.bind(store), clear: store.clear.bind(store),
  };
}

it('validates history frames and composite cursors without changing existing frames [specs/hal-engine-conversation-list/spec.md#36]', () => {
  const cursor = {updatedAt: '2026-10-01T00:00:00.000Z', sessionId: 'older'};
  const valid = [
    {type: 'list_conversations'},
    {type: 'list_conversations', limit: 1},
    {type: 'list_conversations', limit: 200, before: cursor},
  ];
  expect(valid.map(validateMessage)).toEqual(valid.map(data => ({valid: true, data})));
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  }
  for (const before of ['not a date', cursor.updatedAt, null, {}, {updatedAt: cursor.updatedAt}, {sessionId: 'older'}, {...cursor, updatedAt: 'bad'}, {...cursor, sessionId: 1}]) {
    expect(validateMessage({type: 'list_conversations', before})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
  }
  const incoming: IncomingMessage[] = [{type: 'ping', timestamp: 1}, {type: 'user_message', content: 'hello'}];
  const outgoing: OutgoingMessage[] = [
    {type: 'connected', sessionId: 's', message: 'hi', examplePrompts: []},
    {type: 'connected', sessionId: 's', message: 'hi', examplePrompts: [], resumed: false, resumeFailure: 'unknown'},
    {type: 'connected', sessionId: 's', message: 'hi', examplePrompts: [], resumed: true, entryCount: 0},
    {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'hello', timestamp: cursor.updatedAt}},
    {type: 'entry_delta', index: 1, delta: 'hi'}, {type: 'entry_commit', index: 1},
    {type: 'entry_skip', index: 2}, {type: 'stream_end'}, {type: 'pong', timestamp: 1},
    {type: 'error', code: 'SERVER_ERROR', message: 'failed'},
  ];
  expect(incoming.map(validateMessage)).toEqual(incoming.map(data => ({valid: true, data})));
  expect(JSON.parse(JSON.stringify(outgoing))).toEqual(outgoing);
});

it('lists only the connected user on demand, pages ties, bypasses turns and resumes a listed conversation [specs/hal-engine-conversation-list/spec.md#37]', async () => {
  const store = new RecordedStore();
  const timestamp = new Date(Date.now() - 1000).toISOString();
  for (const id of ['a', 'b', 'foreign']) {
    store.create(id, id === 'foreign' ? 'other' : 'owner', {authHeaders: {Authorization: 'private'}})
      .entries.push({role: 'user', content: "'`private ${id}`, timestamp});
  }
  const holding = latch();
  const entered = latch();
  const base = await start(store, {enabled: true}, {hooks: {afterModelResponse: async () => {
    entered.release();
    await holding.promise;
  }}});
  const client = await open(base);
  expect(client.frames.map(frame => frame.type)).toEqual(['"'connected', 'pong']);
  const expected = JSON.parse(JSON.stringify(InMemorySessionStore.prototype.listFor.call(store, 'owner'))) as Row[];
  expect(expected.map(row => row.sessionId)).toEqual([client.frames[0].sessionId, 'b', 'a']);
  expect(await client.request({type: 'list_conversations', userId: 'other'})).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(store.calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  const before = {updatedAt: expected[0].updatedAt, sessionId: expected[0].sessionId};
  expect(await client.request({type: 'list_conversations', limit: 1, before})).toEqual([{type: 'conversation_list', conversations: [expected[1]]}]);
  expect(store.calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
  const tiedCursor = {updatedAt: expected[1].updatedAt, sessionId: expected[1].sessionId};
  expect(await client.request({type: 'list_conversations', limit: 1, before: tiedCursor})).toEqual([{type: 'conversation_list', conversations: [expected[2]]}]);
  const end = {updatedAt: expected[2].updatedAt, sessionId: expected[2].sessionId};
  expect(await client.request({type: 'list_conversations', before: end})).toEqual([{type: 'conversation_list', conversations: []}]);
  try {
    client.send({type: 'user_message', content: 'hello'});
    await entered.promise;
    await client.until(() => client.frames.some(frame => frame.type === 'entry_delta'));
    expect(await client.request({type: 'list_conversations'})).toEqual([{type: 'conversation_list', conversations: expect.any(Array)}]);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    holding.release();
  }
  await client.until(() => client.frames.some(frame => frame.type === 'stream_end'));
  const lists = client.frames.filter(frame => frame.type === 'conversation_list').length;
  await client.barrier();
  expect(client.frames.filter(frame => frame.type === 'conversation_list')).toHaveLength(lists);
  const resumed = await open("'`${base}?sessionId=${expected[1].sessionId}`);
  expect(resumed.frames[0]).toMatchObject({type: '"'connected', sessionId: 'b', resumed: true, entryCount: 1});
  expect(resumed.frames.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry)).toEqual(store.get('b')"'!.entries);
});

it('"'reports unavailable history explicitly and contains store failures without closing the socket [specs/hal-engine-conversation-list/spec.md#38]', async () => {
  const memory = new InMemorySessionStore();
  const mongo = new MongoClient('mongodb://127.0.0.1:1/private-history', {serverSelectionTimeoutMS: 50});
  const collection = mongo.db().collection<MongoSessionDocument>('private-conversations');
  await mongo.close();
  const failedStore = new MongoSessionStore({collection});
  const legacyCollection = {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  };
  const cannotList = new MongoSessionStore({collection: legacyCollection});
  const outcomes: Array<{case: string; frames: Frame[]}> = [];
  const cases = [
    {name: 'default off', store: memory, history: undefined},
    {name: 'explicit off', store: memory, history: {enabled: false}},
    {name: 'legacy store', store: basicStore(memory), history: {enabled: true}},
    {name: 'collection without find', store: {...basicStore(memory), listFor: cannotList.listFor.bind(cannotList)}, history: {enabled: true}},
    {name: 'closed database', store: {...basicStore(memory), listFor: failedStore.listFor.bind(failedStore)}, history: {enabled: true}},
  ];
  for (const scenario of cases) {
    const client = await open(await start(scenario.store, scenario.history));
    const frames = await client.request({type: 'list_conversations'});
    outcomes.push({case: scenario.name, frames});
    expect(client.socket.readyState).toBe(WebSocket.OPEN);
    if (scenario.name === 'closed database') {
      expect(JSON.stringify(frames)).not.toMatch(/Mongo|private-history|private-conversations|127\\.0\\.0\\.1|closed|connect/i);
    }
  }
  expect(outcomes).toEqual(cases.map((scenario, index) => ({case: scenario.name, frames: [{type: 'error', code: index === 4 ? 'SERVER_ERROR' : 'UNSUPPORTED', message: expect.any(String)}]})));
  expect(errors).toEqual(expect.arrayContaining([expect.objectContaining({sessionId: expect.any(String)})]));
  expect(JSON.stringify(errors)).not.toMatch(/credential|private-history|private-conversations/);
  await start(memory, {enabled: true}, undefined, false);
  expect(JSON.stringify(warnings)).toMatch(/history/i);
  expect(JSON.stringify(warnings)).toMatch(/resume/i);
});
